class CourseModel { final String id,name,levelId,description; final DateTime startDate,endDate; final double passingScore; final bool active; const CourseModel({required this.id,required this.name,required this.levelId,required this.description,required this.startDate,required this.endDate,this.passingScore=60,this.active=true}); Map<String,dynamic> toMap()=>{'name':name,'levelId':levelId,'description':description,'startDate':startDate.toIso8601String(),'endDate':endDate.toIso8601String(),'passingScore':passingScore,'active':active}; factory CourseModel.fromMap(String id,Map<String,dynamic> m)=>CourseModel(id:id,name:m['name']??'',levelId:m['levelId']??'',description:m['description']??'',startDate:DateTime.tryParse(m['startDate']??'')??DateTime.now(),endDate:DateTime.tryParse(m['endDate']??'')??DateTime.now(),passingScore:(m['passingScore']??60).toDouble(),active:m['active']??true); }